<template>
  <a-card :bordered="false">
    <div class="card-title">{{ $route.meta.title }}</div>
    <div class="table-operator">
      <!-- 搜索板块 -->
      <a-row class="row-item-search">
        <a-form class="search-form" :form="searchForm" layout="inline" @submit="handleSearch">
          <a-form-item label="商品名称">
            <a-input v-decorator="['title']" placeholder="请输入商品名称" />
          </a-form-item>
          <a-form-item label="商品编码">
            <a-input v-decorator="['no']" placeholder="请输入商品编码" />
          </a-form-item>
          <a-form-item label="商品分类">
            <a-tree-select
              :treeData="categoryListTree"
              :dropdownStyle="{ maxHeight: '500px', overflow: 'auto' }"
              allowClear
              v-decorator="['category_ids', { initialValue: 0 }]"
            ></a-tree-select>
          </a-form-item>
          <a-form-item class="search-btn">
            <a-button type="primary" icon="search" html-type="submit">搜索</a-button>
          </a-form-item>
          <!-- <a-form-item class="search-btn">
            <a-button @click="handleReset">重置</a-button>
          </a-form-item>-->
        </a-form>
      </a-row>
      <!-- 操作板块 -->
      <div class="row-item-tab clearfix">
        <div class="tab-list fl-l">
          <a-radio-group v-model="queryParam.type" @change="handleType">
            <a-radio-button value="intra-city" v-if="$store.getters.role.name != '旅游线路管理员' && $store.getters.role.name != '跨地商品管理员'">同城商品</a-radio-button>
            <a-radio-button value="physical" v-if="$store.getters.role.name == '跨地商品管理员' || $store.getters.role.name == '超级管理员'">跨地商品</a-radio-button>
            <a-radio-button value="travel" v-if="$store.getters.role.name == '旅游线路管理员' || $store.getters.role.name == '超级管理员'">旅游线路</a-radio-button>
            <a-radio-button value="verification" v-if="$store.getters.role.name == '旅游线路管理员' || $store.getters.role.name == '超级管理员'">核销卡券</a-radio-button>
            <a-radio-button value="virtual" v-if="$store.getters.role.name == '跨地商品管理员' || $store.getters.role.name == '超级管理员'">线下交易</a-radio-button>
            <a-radio-button value="course" v-if="$store.getters.role.name == '超级管理员'">课程</a-radio-button>
          </a-radio-group>
        </div>
        <div class="tab-list fl-l">
          <a-radio-group :defaultValue="queryParam.listType" @change="handleStatus">
            <a-radio-button value="all">全部</a-radio-button>
            <a-radio-button value="on_sale">出售中</a-radio-button>
            <a-radio-button value="off_sale">已下架</a-radio-button>
            <a-radio-button value="sold_out">已售罄</a-radio-button>
          </a-radio-group>
        </div>
        <a-button
          v-if="$auth('products.intra-city.skus.create') && queryParam.type == 'intra-city'"
          class="fl-l"
          type="primary"
          icon="plus"
          @click="handleAdd"
        >添加商品</a-button>
        <div v-else>
          <a-button
            class="fl-l"
            type="primary"
            icon="plus"
            @click="handleCreate"
          >{{ queryParam.type == 'travel' ? '新增线路' : '新增商品' }}</a-button>
          <a-tooltip class="ml-10" placement="right">
            <template slot="title">
              <span>非同城商品默认不会展示，需要在[页面设计]中配置对应展示的商品类型</span>
            </template>
            <a-button type="dashed" shape="circle" icon="info" />
          </a-tooltip>
        </div>
        <div v-if="selectedRowKeys.length" class="button-group">
          <a-button-group class="ml-10">
            <a-button
              icon="arrow-up"
              @click="handleUpdateStatus(selectedRowKeys, true)"
            >上架</a-button>
            <a-button
              icon="arrow-down"
              @click="handleUpdateStatus(selectedRowKeys, false)"
            >下架</a-button>
            <a-button v-action:products.*.delete icon="delete" @click="handleDelete(selectedRowKeys)">删除</a-button>
          </a-button-group>
        </div>
      </div>
    </div>
    <s-table
      ref="table"
      rowKey="id"
      :loading="isLoading"
      :columns="columns"
      :data="loadData"
      :rowSelection="rowSelection"
      :pageSize="15"
    >
      <!-- 商品图片 -->
      <span slot="image" slot-scope="text">
        <a title="点击查看原图" :href="text" target="_blank">
          <img width="50" height="50" :src="text" alt="商品图片" />
        </a>
      </span>
      <!-- 商品名称 -->
      <span slot="goods_title" slot-scope="text">
        <p class="twoline-hide" style="width: 270px;">{{ text }}</p>
      </span>
      <!-- 商品状态 -->
      <span slot="on_sale" slot-scope="text, item">
        <a-tag
          class="cur-p"
          :color="text ? 'green' : 'red'"
          @click="handleUpdateStatus([item.id], !text)"
        >{{ text ? '在售' : '下架' }}</a-tag>
      </span>
      <!-- 操作项 -->
      <div class="actions" slot="action" slot-scope="text, item">
        <a v-if="$auth('products.*.update')" @click="handleEdit(item)">编辑</a>
        <a v-if="$auth('products.*.delete')" @click="handleDelete([item.id])">删除</a>
        <a-popover trigger="hover" @visibleChange="v => {
          if (!v) return;
          showQRCode(item)
        }">
          <template #title>
            <a-typography-text code ellipsis style="width: 120px">pages/goods/goods?id={{item.id}}</a-typography-text>
          </template>
          <template #content>
            <a-spin v-if="QRcode[item.id] && QRcode[item.id]=='loading'" />
            <img v-else-if="QRcode[item.id]" :src="QRcode[item.id]" width="100" height="100" style="margin:auto; display:block" />
          </template>
          <a>链接</a>
        </a-popover>
      </div>
    </s-table>

    <!-- 从主仓库中添加商品 -->
    <a-drawer
      title="从主仓库添加商品"
      placement="right"
      :closable="false"
      :visible="visibleGoodsPicker"
      :width="640"
    >
      <template v-if="showPickerList">
        <div class="table-operator">
          <!-- 搜索板块 -->
          <a-row class="row-item-search">
            <a-form class="search-form" layout="inline">
              <a-form-item label="商品分类">
                <a-tree-select
                  v-model="pickerParams.category_ids"
                  :treeData="categoryListTree"
                  defaultValue="0"
                  :dropdownStyle="{ maxHeight: '500px', overflow: 'auto' }"
                  allowClear
                  @change="searchGoodsPicker(pickerParams.search)"
                ></a-tree-select>
              </a-form-item>
              <a-input-search
                v-model="pickerParams.search"
                style="max-width: 250px; min-width: 150px;"
                placeholder="搜索商品名称"
                @search="searchGoodsPicker"
              />
            </a-form>
          </a-row>
        </div>
        <s-table
          ref="goodsPickerTable"
          rowKey="id"
          :loading="isLoading"
          :columns="columnsGoodsPicker"
          :data="loadGoodsPickerData"
          :rowSelection="{
            selectedRowKeys: selectedRowKeysPicker,
            onChange: keys => selectedRowKeysPicker = keys
          }"
          :pageSize="16"
        >
          <!-- 商品图片 -->
          <span slot="image" slot-scope="text">
            <a title="点击查看原图" :href="text" target="_blank">
              <img width="50" height="50" :src="text" alt="商品图片" />
            </a>
          </span>
          <!-- 商品名称 -->
          <span slot="goods_title" slot-scope="text">
            <p class="twoline-hide" style="width: 270px;">{{ text }}</p>
          </span>
        </s-table>
      </template>
      <template v-else>
        <div style="height: 400px; display: flex; flex-direction: column; align-items: center; justify-content: center;">
          <a-input-search
            placeholder="搜索商品名称"
            @search="searchGoodsPicker"
            size="large"
            style=""
          />
        </div>
      </template>
      <div
        :style="{
          position: 'absolute',
          right: 0,
          bottom: 0,
          width: '100%',
          borderTop: '1px solid #e9e9e9',
          padding: '10px 16px',
          background: '#fff',
          textAlign: 'right',
          zIndex: 1,
        }"
      >
        <a-button type="primary" @click="handleCreate" style="float: left">创建新商品</a-button>
        <a-button :style="{ marginRight: '8px' }" @click="visibleGoodsPicker=false">取消</a-button>
        <a-button type="primary" @click="submitGoodspicker" :loading="isSavingPicking">添加</a-button>
      </div>
    </a-drawer>
  </a-card>
</template>

<script>
import * as GoodsApi from '@/api/goods'
import * as WechatApi from '@/api/wechat'
import { ContentHeader, STable } from '@/components'
import CategoryModel from '@/common/model/Category'

// 表格表头
const columns = [
  {
    title: '商品ID',
    dataIndex: 'id'
  },
  {
    title: '商品图片',
    dataIndex: 'image',
    scopedSlots: { customRender: 'image' }
  },
  {
    title: '商品名称',
    dataIndex: 'title',
    scopedSlots: { customRender: 'goods_title' }
  },
  {
    title: '最低价格',
    dataIndex: 'price_lowest',
  },
  {
    title: '总销量',
    dataIndex: 'sold_count'
  },
  {
    title: '仓储库存',
    dataIndex: 'stock'
  },
  {
    title: '库存总量',
    dataIndex: 'stock_total'
  },
  {
    title: '状态',
    dataIndex: 'on_sale',
    scopedSlots: { customRender: 'on_sale' }
  },
  {
    title: '添加时间',
    dataIndex: 'created_at'
  },
  {
    title: '操作',
    dataIndex: 'action',
    width: '180px',
    scopedSlots: { customRender: 'action' }
  }
]

export default {
  name: 'Index',
  components: {
    ContentHeader,
    STable
  },
  data () {
    return {
      // 当前表单元素
      searchForm: this.$form.createForm(this),
      // 商品分类列表
      categoryListTree: [],
      // 查询参数
      queryParam: {
        type: 'intra-city',
        listType: 'all',
      },
      tabParams: {},
      // 正在加载
      isLoading: false,
      // 表头
      columns,
      // 选择的元素
      selectedRowKeys: [],
      // 加载数据方法 必须为 Promise 对象
      loadData: param => {
        return GoodsApi.list({ ...param, ...this.queryParam, ...this.tabParams, ...{store_id: this.$store.getters.storeId} })
          .then(response => {
            return response
          })
      },
      // 主库挑选商品
      visibleGoodsPicker: false,
      showPickerList: false,
      isSavingPicking: false,
      selectedRowKeysPicker: [],
      pickerParams: {type: 'intra-city'},
      columnsGoodsPicker: columns.filter(c => /^(id|image|title|price_lowest|created_at)$/.test(c.dataIndex)),
      loadGoodsPickerData: param => {
        return GoodsApi.list({ ...param, ...this.pickerParams, ...{except_store_id: this.$store.getters.storeId} })
          .then(response => {
            return response
          })
      },
      // 二维码
      QRcode: {},
    }
  },
  watch: {
    'queryParam.listType': {
      immediate: true,
      handler (val){
        if (this.queryParam.listType == 'on_sale') this.tabParams = {on_sale: true}
        else if (this.queryParam.listType == 'off_sale') this.tabParams = {on_sale: false}
        else if (this.queryParam.listType == 'sold_out') this.tabParams = {stock: 0}
        else {this.tabParams = {}}
        this.handleRefresh(true)
      }
    }
  },
  created () {
    // 默认的查询参数
    if (this.$route.query.listType) {
      this.queryParam.listType = this.$route.query.listType
    }
    // 获取商品分类列表
    this.getCategoryList()
  },
  computed: {
    rowSelection () {
      return {
        selectedRowKeys: this.selectedRowKeys,
        onChange: this.onSelectChange
      }
    }
  },
  methods: {

    /**
     * 选中项发生变化时的回调
     */
    onSelectChange (selectedRowKeys) {
      this.selectedRowKeys = selectedRowKeys
    },

    // 切换tab
    handleType (e) {
      this.queryParam.types = [e.target.value]
      this.handleRefresh(true)
    },
    handleStatus (e) {
      this.queryParam.listType = e.target.value
    },

    // 确认搜索
    handleSearch (e) {
      e.preventDefault()
      this.searchForm.validateFields((error, values) => {
        if (!error) {
          this.queryParam = { ...this.queryParam, ...values }
          this.handleRefresh(true)
        }
      })
    },

    // 重置搜索表单
    handleReset () {
      this.searchForm.resetFields()
    },

    // 获取分类列表
    getCategoryList () {
      this.isLoading = true
      CategoryModel.getListFromScreen()
        .then(selectList => {
          this.categoryListTree = selectList
        })
        .finally(result => {
          this.isLoading = false
        })
    },

    // 修改商品状态(上下架)
    handleUpdateStatus (goodsIds, state = true) {
      if (!this.$auth('products.*.update')) {
        return false
      }
      this.isLoading = true
      GoodsApi.state({ goodsIds, state })
        .then(result => {
          // 显示成功
          this.$message.success(result.message, 1.5)
          this.handleRefresh()
        })
        .finally(result => { this.isLoading = false })
    },

    /**
     * 删除记录
     */
    handleDelete (goodsIds) {
      const app = this
      const modal = this.$confirm({
        title: '您确定要删除该记录吗?',
        content: '删除后不可恢复',
        onOk () {
          const promiseGoodsApi = app.queryParam.type == 'intra-city' ? GoodsApi.deleteSkus({product_ids: goodsIds, store_id: app.$store.getters.storeId}) : GoodsApi.deleted({ids: goodsIds})
          return promiseGoodsApi.then(result => {
              app.$message.success(result.message, 1.5)
              app.handleRefresh()
            })
            .finally(result => {
              modal.destroy()
            })
        }
      })
    },

    /**
     * 新增记录
     */
    handleAdd () {
      this.visibleGoodsPicker = true
    },
    handleCreate () {
      this.$router.push('/goods/create')
    },

    /**
     * 编辑记录
     */
    handleEdit (item) {
      this.$router.push({ path: '/goods/update', query: { goodsId: item.id } })
    },

    /**
     * 刷新列表
     * @param Boolean bool 强制刷新到第一页
     */
    handleRefresh (bool = false) {
      this.selectedRowKeys = []
      this.$refs.table?.refresh(bool)
    },

    /**
     * 主库挑选商品
     */
    handleSearchGoodsPicker (e) {
      e.preventDefault()
      this.pickerSearchForm.validateFields((error, values) => {
        if (!error) {
          this.pickerParams = { ...this.pickerParams, ...values }
          this.selectedRowKeysPicker = []
          this.$refs.goodsPickerTable.refresh(true)
        }
      })
    },
    searchGoodsPicker (value) {
      this.showPickerList = true
      this.pickerParams.search = value
      this.pickerParams = {...this.pickerParams}
      this.$refs.goodsPickerTable?.refresh(true)
    },
    submitGoodspicker () {
      this.isSavingPicking = true
      GoodsApi.copySku({ product_ids: this.selectedRowKeysPicker, store_id: this.$store.getters.storeId })
        .then(result => {
          this.$message.success('已添加选中商品到本仓储', 1.5)
          this.visibleGoodsPicker = false
          this.handleRefresh(true)
        })
        .finally(result => {
          this.isSavingPicking = false
        })
    },

    /**
     * 生成二维码预览
     */
    async showQRCode(item) {
      if (this.QRcode[item.id]) return;
      this.QRcode[item.id] = 'loading';
      this.QRcode = {...this.QRcode};
      let QRcodeData = await WechatApi.qrcode('pages/goods/goods?id=' + item.id);
      this.QRcode = {...this.QRcode};
      this.QRcode[item.id] = QRcodeData.base64;
    },
  }
}
</script>
<style lang="less" scoped>
.ant-card-body {
  padding: 22px 29px 25px;
}
// 筛选tab
.tab-list {
  margin-right: 20px;
}
</style>
